# tests/hello_test.py
import unittest
from hello import say_hello

class TestHello(unittest.TestCase):
    def test_say_hello(self):
        with self.assertLogs(level='INFO') as log:
            say_hello()
        self.assertIn('Hello, World!', log.output[0])

if __name__ == '__main__':
    unittest.main()
